CREATE TABLE config (id INTEGER PRIMARY KEY CHECK(id=1), version INTEGER NOT NULL, audience TEXT NOT NULL, signing_key BLOB NOT NULL);
CREATE TABLE accounts (id TEXT PRIMARY KEY, tenant TEXT NOT NULL UNIQUE, issuer TEXT NOT NULL, subject TEXT NOT NULL, UNIQUE(issuer,subject));
CREATE TABLE sessions (token TEXT PRIMARY KEY, csrf TEXT NOT NULL, account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, expires INTEGER NOT NULL);
CREATE TABLE pairs (id TEXT PRIMARY KEY, code TEXT UNIQUE, poll TEXT NOT NULL UNIQUE, request TEXT NOT NULL, expires INTEGER NOT NULL, claim TEXT, account TEXT REFERENCES accounts(id) ON DELETE CASCADE, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE nodes (id TEXT PRIMARY KEY, account TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE, certificate TEXT NOT NULL, revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE challenges (nonce TEXT PRIMARY KEY, node TEXT NOT NULL REFERENCES nodes(id) ON DELETE CASCADE, preview TEXT NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE audit (sequence INTEGER PRIMARY KEY AUTOINCREMENT, timestamp INTEGER NOT NULL, kind TEXT NOT NULL, actor TEXT NOT NULL, resource TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audit BEGIN SELECT RAISE(ABORT,'append only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audit BEGIN SELECT RAISE(ABORT,'append only'); END;
